      "id": 1,
      "claim": "The troposphere is the lowest layer of Earth’s atmosphere, extending from the surface to roughly 8–18 km altitude.",
      "evidence": "Standard atmospheric model definitions (e.g., US Standard Atmosphere).",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Air pressure and density decrease exponentially with height according to the barometric formula, so any altitude above the troposphere has lower density than the surface of the troposphere.",
      "evidence": "Barometric equation P(h)=P0 exp(-Mgh/RT) and the ideal‑gas relation ρ = P/(RT).",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Approximately 75–80 % of the total atmospheric mass is contained within the troposphere, giving it the greatest average density of all atmospheric layers.",
      "evidence": "Atmospheric mass distribution data from climatology textbooks and NASA atmospheric profiles.",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Because the troposphere is the lowest layer and contains the majority of atmospheric mass, it is the layer with the greatest density.",
      "evidence": "Logical combination of steps 1–3.",
      "weight": 0.15,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Option (B) ‘greatest density’ matches this property, whereas (A) ozone is maximal in the stratosphere, (C) highest altitude refers to the exosphere/thermosphere, and (D) coldest temperatures occur in the mesosphere.",
      "evidence": "Known atmospheric composition and temperature profiles.",
      "weight": 0.10,
      "depends_on": [4]
    }
  ],
  "answer": "B",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Ozone concentration peaks in the stratosphere, not the troposphere."
    },
    {
      "answer": "C",
      "reason_rejected": "The troposphere is the lowest, not the highest, atmospheric layer."
    },
    {
      "answer": "D",
      "reason_rejected": "The coldest atmospheric temperatures are found in the mesosphere (mesopause)."
    }
  ]
}
